});

test('invoiceTotals applies bulk discount at 10 units', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 10000;
  const bulkDiscount = roundCents(lineSubtotal * 0.025);
  assert.equal(totals.subtotal, lineSubtotal);
  assert.equal(totals.discount, bulkDiscount);
  assert.equal(totals.total, lineSubtotal - bulkDiscount);
});

test('invoiceTotals does not apply bulk discount below 10 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 9000;
  assert.equal(totals.subtotal, lineSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, lineSubtotal);
});

test('invoiceTotals applies bulk discount after line discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 10000;
  const lineDiscount = roundCents(lineSubtotal * 0.1);
  const amountAfterDiscount = lineSubtotal - lineDiscount;
  const bulkDiscount = roundCents(amountAfterDiscount * 0.025);
  const expectedTotal = roundCents(lineSubtotal - lineDiscount - bulkDiscount);
  assert.equal(totals.subtotal, lineSubtotal);
  assert.equal(totals.discount, lineDiscount + bulkDiscount);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals bulk discount applies to correct amount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 4000, discountPercent: 10, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 40000;
  const lineDiscount = roundCents(40000 * 0.1);
  const amountAfterLineDiscount = 40000 - lineDiscount;
  const bulkDiscount = roundCents(amountAfterLineDiscount * 0.025);
  assert.equal(totals.discount, lineDiscount + bulkDiscount);
});

test('invoiceTotals bulk discount with VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 10000;
  const bulkDiscount = roundCents(lineSubtotal * 0.025);
  const amountForVAT = lineSubtotal - bulkDiscount;
  const expectedVAT = roundCents(amountForVAT * 0.21);
  assert.equal(totals.discount, bulkDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, lineSubtotal - bulkDiscount + expectedVAT);
});

test('invoiceTotals bulk discount with both line discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 10000;
  const lineDiscount = roundCents(lineSubtotal * 0.1);
  const amountAfterLineDiscount = lineSubtotal - lineDiscount;
  const bulkDiscount = roundCents(amountAfterLineDiscount * 0.025);
  const amountForVAT = lineSubtotal - lineDiscount - bulkDiscount;
  const expectedVAT = roundCents(amountForVAT * 0.21);
  assert.equal(totals.discount, lineDiscount + bulkDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, lineSubtotal - lineDiscount - bulkDiscount + expectedVAT);
});

test('invoiceTotals multiple lines with mixed bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1Subtotal = 5000;
  const line2Subtotal = 10000;
  const expectedSubtotal = line1Subtotal + line2Subtotal;
  const line2BulkDiscount = roundCents(line2Subtotal * 0.025);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, line2BulkDiscount);
  assert.equal(totals.total, expectedSubtotal - line2BulkDiscount);
});

test('invoiceTotals bulk discount at exactly 10 units', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(totals.discount > 0);
});

test('invoiceTotals no bulk discount at 9 units', () => {
  const invoice = {
    lines: [{ qty: 9, unitPrice: 100, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
});

test('invoiceTotals bulk discount with large quantity', () => {
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 100000;
  const bulkDiscount = roundCents(lineSubtotal * 0.025);
  assert.equal(totals.discount, bulkDiscount);
});

test('invoiceTotals bulk discount with tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const totals = invoiceTotals(r.value);
  const lineSubtotal = 10 * 8500;
  const tierDiscount = roundCents(lineSubtotal * 0.05);
  const amountAfterTierDiscount = lineSubtotal - tierDiscount;
  const bulkDiscount = roundCents(amountAfterTierDiscount * 0.025);
  assert.equal(totals.discount, tierDiscount + bulkDiscount);
});

test('invoiceTotals multiple lines with different bulk discount scenarios', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
      { qty: 10, unitPrice: 2000, discountPercent: 10, vatRate: 21 },
      { qty: 15, unitPrice: 2000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);

  const line1Subtotal = 10000;
  const line1Discount = 0;
  const line1BulkDiscount = 0;
  const line1Amount = line1Subtotal - line1Discount - line1BulkDiscount;

  const line2Subtotal = 20000;
  const line2Discount = roundCents(line2Subtotal * 0.1);
  const line2BulkDiscount = roundCents((line2Subtotal - line2Discount) * 0.025);
  const line2Amount = line2Subtotal - line2Discount - line2BulkDiscount;

  const line3Subtotal = 30000;
  const line3Discount = 0;
  const line3BulkDiscount = roundCents(line3Subtotal * 0.025);
  const line3Amount = line3Subtotal - line3Discount - line3BulkDiscount;

  const totalDiscount = line1Discount + line1BulkDiscount + line2Discount + line2BulkDiscount + line3Discount + line3BulkDiscount;
  const totalVAT = roundCents(line1Amount * 0.21) + roundCents(line2Amount * 0.21) + roundCents(line3Amount * 0.21);
  const expectedSubtotal = line1Subtotal + line2Subtotal + line3Subtotal;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, totalDiscount);
  assert.equal(totals.vat, totalVAT);
  assert.equal(totals.total, expectedSubtotal - totalDiscount + totalVAT);
});

test('invoiceTotals bulk discount does not affect voucher application', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    voucher: { code: 'SAVE', amount: 100 },
  };
  const totals = invoiceTotals(invoice);
  const lineSubtotal = 10000;
  const bulkDiscount = roundCents(lineSubtotal * 0.025);
  const expected = lineSubtotal - bulkDiscount - 100;
  assert.equal(totals.total, expected);
});

test('invoiceTotals bulk discount calculates correctly with real invoice', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });
  const totals = invoiceTotals(r.value);
  const lineSubtotal = 100 * 370;
  const bulkDiscount = roundCents(lineSubtotal * 0.025);
  assert.ok(totals.discount >= bulkDiscount);
  assert.ok(totals.total > 0);
});

