  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with 21% VAT rate', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  const lineAmount = 42500;
  const expectedVAT = roundCents(lineAmount * 0.21);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals with mixed VAT rates on multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500, discountPercent: 0, vatRate: 21 }, // Design work
      { qty: 5, unitPrice: 37, discountPercent: 0, vatRate: 9 },   // Print
      { qty: 1, unitPrice: 60000, discountPercent: 0, vatRate: 0 },  // Workshop
    ],
  };
  const totals = invoiceTotals(invoice);
  const line1VAT = roundCents(42500 * 0.21);
  const line2VAT = roundCents(185 * 0.09);
