test('applyVoucher requires draft status', () => {
  const issuedInvoice = {
    customerId: 'C-001',
    number: 'INV-2026-0001',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0, vatRate: 21, name: 'Design work (hour)', unitPrice: 8500 }],
  };
  assert.deepEqual(
    applyVoucher(issuedInvoice, { code: 'SAVE10', amount: 5000 }),
    { ok: false, error: 'NOT_DRAFT' }
  );
});

test('applyVoucher requires positive integer amount', () => {
  const draftInvoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 0, vatRate: 21, name: 'Design work (hour)', unitPrice: 8500 }],
  };

  assert.deepEqual(
    applyVoucher(draftInvoice, { code: 'SAVE10', amount: 0 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );

  assert.deepEqual(
    applyVoucher(draftInvoice, { code: 'SAVE10', amount: -5000 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );

  assert.deepEqual(
    applyVoucher(draftInvoice, { code: 'SAVE10', amount: 5000.50 }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );

  assert.deepEqual(
    applyVoucher(draftInvoice, { code: 'SAVE10', amount: '5000' }),
    { ok: false, error: 'AMOUNT_INVALID' }
  );
});

test('applyVoucher prevents multiple vouchers', () => {
