  const secondVoucher = applyVoucher(withVoucher.value, { code: 'SAVE20', amount: 10000 });
  assert.deepEqual(secondVoucher, { ok: false, error: 'VOUCHER_EXISTS' });
});

test('applyVoucher adds voucher to draft invoice', () => {
