});

test('invoiceTotals calculates total with voucher', () => {
  const r = createInvoice({
    customerId: 'C-002', // standard tier
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 10000 });
  const totals = invoiceTotals(withVoucher.value);

  assert.equal(totals.voucher, 10000);
  assert.equal(totals.total, totals.subtotal + totals.vat - 10000);
});

test('invoiceTotals voucher formula: total = subtotal - discount + vat - voucher', () => {
  const r = createInvoice({
    customerId: 'C-001', // gold tier: 5% discount
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const withVoucher = applyVoucher(r.value, { code: 'SAVE20', amount: 20000 });
  const totals = invoiceTotals(withVoucher.value);

  const expectedTotal = totals.subtotal - totals.discount + totals.vat - 20000;
  assert.equal(totals.total, Math.max(0, expectedTotal));
});

test('invoiceTotals voucher with no discount', () => {
  const invoice = {
    lines: [{ qty: 10, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'SAVE10', amount: 5000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.discount, 0);
  assert.equal(totals.voucher, 5000);
  assert.equal(totals.total, totals.subtotal + totals.vat - 5000);
});

test('invoiceTotals with multiple invoice components', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5, discountPercent: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  const withVoucher = applyVoucher(r.value, { code: 'WELCOME', amount: 15000 });
  const totals = invoiceTotals(withVoucher.value);

  const expectedTotal = totals.subtotal - totals.discount + totals.vat - 15000;
  assert.equal(totals.total, Math.max(0, expectedTotal));
  assert.equal(totals.voucher, 15000);
});

test('invoiceTotals total clamped at 0 with large voucher', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 8500, discountPercent: 0, vatRate: 21 }],
    voucher: { code: 'FREE', amount: 50000 },
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.total >= 0, true);
  assert.equal(totals.total, 0);
});

test('applyVoucher preserves other invoice fields', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET14',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });

  const withVoucher = applyVoucher(r.value, { code: 'SAVE10', amount: 5000 });
  assert.equal(withVoucher.value.customerId, r.value.customerId);
  assert.equal(withVoucher.value.issueDate, r.value.issueDate);
  assert.equal(withVoucher.value.terms, r.value.terms);
  assert.equal(withVoucher.value.dueDate, r.value.dueDate);
  assert.equal(withVoucher.value.status, r.value.status);
  assert.equal(withVoucher.value.lines.length, r.value.lines.length);
});

